CREATE OR REPLACE FUNCTION public.fn_ca_retire_welcome_certification_club(p_club_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_post_reset boolean;
  v_leases jsonb; v_origins jsonb; v_board jsonb; v_schedule jsonb;
  v_prepared jsonb; v_retired jsonb; v_child numeric:=0;
BEGIN
  SELECT EXISTS(SELECT 1 FROM public.club_welcome_reset_receipts r
    WHERE r.club_id=p_club_id AND COALESCE((r.result->>'ok')::boolean,false))
    INTO v_post_reset;
  IF v_post_reset THEN
    v_prepared:=public.fn_ca_prepare_post_reset_welcome_certification_fixture(p_club_id);
    IF NOT COALESCE((v_prepared->>'prepared')::boolean,false) THEN
      RAISE EXCEPTION 'POST_RESET_CERTIFICATION_PREPARATION_REFUSED: %',
        COALESCE(v_prepared->>'reason','unknown') USING ERRCODE='55000';
    END IF;
  ELSE
    v_leases:=public.fn_ca_prepare_unused_welcome_certification_board_leases(p_club_id);
    v_origins:=public.fn_ca_prepare_unused_welcome_certification_board_origins(p_club_id);
    v_board:=public.fn_ca_prepare_unused_welcome_certification_board_games(p_club_id);
    v_schedule:=public.fn_ca_prepare_unused_welcome_certification_schedule_spawns(p_club_id);
    v_prepared:=public.fn_ca_prepare_unused_welcome_certification_fixture(p_club_id);
    v_child:=COALESCE((v_prepared->>'child_chips_retired')::numeric,0);
  END IF;
  v_retired:=public.fn_ca_retire_certification_club(p_club_id,p_reason);
  IF COALESCE((v_prepared->>'prepared')::boolean,false)
     AND NOT COALESCE((v_retired->>'success')::boolean,false) THEN
    RAISE EXCEPTION 'WELCOME_CERTIFICATION_RETIREMENT_REFUSED: %',
      COALESCE(v_retired->>'error','unknown') USING ERRCODE='55000';
  END IF;
  IF COALESCE((v_retired->>'success')::boolean,false)
     AND NOT COALESCE((v_retired->>'already_gone')::boolean,false) THEN
    v_retired:=jsonb_set(v_retired,'{chips_retired}',
      to_jsonb(round(COALESCE((v_retired->>'chips_retired')::numeric,0)+v_child,2)),true);
    v_retired:=v_retired||jsonb_build_object('child_chips_retired',v_child,
      'cleanup_state',CASE WHEN v_post_reset THEN 'post_reset' ELSE 'pristine' END,
      'board_tournament_leases_removed',COALESCE((v_leases->>'tournament_leases_removed')::integer,0),
      'board_origins_removed',COALESCE((v_origins->>'origins_removed')::integer,0),
      'board_tournaments_removed',COALESCE((v_board->>'tournaments_removed')::integer,0),
      'board_tables_removed',COALESCE((v_board->>'tables_removed')::integer,0),
      'schedule_tournaments_removed',COALESCE((v_schedule->>'tournaments_removed')::integer,0),
      'schedule_tables_removed',COALESCE((v_schedule->>'tables_removed')::integer,0));
  END IF;
  RETURN v_retired;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_create_seat_first_game_atomic(p_tournament_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_existing public.tournaments%ROWTYPE;
  v_existing_table public.tables%ROWTYPE;
  v_existing_table_count integer;
  v_created public.tournaments%ROWTYPE;
  v_table_id uuid;
  v_club_id uuid;
  v_union_id uuid;
  v_name text;
  v_game_type text;
  v_table_variant text;
  v_variant text;
  v_tournament_type text;
  v_buy_in numeric;
  v_buy_in_fee numeric;
  v_guarantee numeric;
  v_starting_chips integer;
  v_max_players integer;
  v_min_players integer;
  v_table_size integer;
  v_blinds jsonb;
  v_payouts jsonb;
  v_start_time timestamptz;
  v_late_reg_levels integer;
  v_late_reg_mins integer;
  v_satellite_target_id uuid;
  v_satellite_seats integer;
  v_short_description text;
  v_requested_current_players integer;
  v_requested_status text;
  v_first_level jsonb;
  v_small_blind numeric;
  v_big_blind numeric;
  v_admission_abi text;
BEGIN
  IF p_tournament_id IS NULL OR p_config IS NULL OR jsonb_typeof(p_config) <> 'object' THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_REQUEST'
      USING ERRCODE = '22023';
  END IF;

  /* Every accepted request key must be represented by the durable pair below.
     Rejecting unknown keys prevents an idempotent replay from appearing exact
     after a caller adds configuration this creator silently ignores. */
  IF EXISTS (
    SELECT 1
      FROM jsonb_object_keys(p_config) AS supplied(key)
     WHERE supplied.key NOT IN (
       'club_id', 'union_id', 'name', 'game_type', 'variant',
       'tournament_type', 'buy_in_amount', 'buy_in_fee', 'guaranteed_prize',
       'starting_chips', 'max_players', 'min_players', 'table_size',
       'current_players', 'status', 'blind_structure', 'payout_structure',
       'start_time', 'late_reg_levels', 'late_reg_mins',
       'satellite_target_id', 'satellite_seats', 'short_description',
       'spin_multiplier', 'spin_locked_tiers'
     )
  ) THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_UNKNOWN_CONFIG_KEY'
      USING ERRCODE = '22023';
  END IF;

  /* This is an entry-producing transaction. It takes the same first lock as
     every purchase path, before the idempotency key or either game row. */
  PERFORM pg_advisory_xact_lock_shared(530090, 1);
  v_admission_abi:=public.fn_ca_lock_mtt_admission_contract();
  IF public.fn_entry_purchases_frozen() THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'platform_frozen');
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('ca:seat-first-create:' || p_tournament_id::text, 0)
  );

  v_club_id := NULLIF(p_config->>'club_id', '')::uuid;
  v_union_id := NULLIF(p_config->>'union_id', '')::uuid;
  v_name := NULLIF(btrim(p_config->>'name'), '');
  v_game_type := NULLIF(btrim(p_config->>'game_type'), '');
  v_table_variant := lower(v_game_type);
  v_variant := lower(NULLIF(btrim(p_config->>'variant'), ''));
  v_tournament_type := upper(NULLIF(btrim(p_config->>'tournament_type'), ''));
  v_buy_in := COALESCE(NULLIF(p_config->>'buy_in_amount', '')::numeric, 0);
  v_buy_in_fee := COALESCE(NULLIF(p_config->>'buy_in_fee', '')::numeric, 0);
  v_guarantee := COALESCE(NULLIF(p_config->>'guaranteed_prize', '')::numeric, 0);
  v_starting_chips := NULLIF(p_config->>'starting_chips', '')::integer;
  v_max_players := NULLIF(p_config->>'max_players', '')::integer;
  v_min_players := COALESCE(NULLIF(p_config->>'min_players', '')::integer, v_max_players);
  v_table_size := COALESCE(NULLIF(p_config->>'table_size', '')::integer, v_max_players);
  v_blinds := p_config->'blind_structure';
  v_payouts := COALESCE(p_config->'payout_structure', '[]'::jsonb);
  v_start_time := NULLIF(p_config->>'start_time', '')::timestamptz;
  v_late_reg_levels := COALESCE(NULLIF(p_config->>'late_reg_levels', '')::integer, 0);
  v_late_reg_mins := COALESCE(NULLIF(p_config->>'late_reg_mins', '')::integer, 0);
  v_satellite_target_id := NULLIF(p_config->>'satellite_target_id', '')::uuid;
  v_satellite_seats := NULLIF(p_config->>'satellite_seats', '')::integer;
  v_short_description := NULLIF(btrim(p_config->>'short_description'), '');
  v_requested_current_players :=
    COALESCE(NULLIF(p_config->>'current_players', '')::integer, 0);
  v_requested_status :=
    upper(COALESCE(NULLIF(btrim(p_config->>'status'), ''), 'REGISTERING'));

  IF v_club_id IS NULL
     OR v_name IS NULL
     OR v_game_type IS NULL
     OR v_variant IS NULL
     OR v_tournament_type IS NULL
     OR v_starting_chips IS NULL OR v_starting_chips <= 0
     OR v_max_players IS NULL OR v_max_players < 2 OR v_max_players > 3
     OR v_min_players < 2 OR v_min_players > v_max_players
     OR v_table_size <> v_max_players
     OR v_start_time IS NULL
     OR jsonb_typeof(v_blinds) <> 'array'
     OR jsonb_array_length(v_blinds) = 0
     OR jsonb_typeof(v_payouts) <> 'array'
     OR NOT (v_variant = 'spin' OR v_max_players = 2)
     OR v_tournament_type NOT IN ('SPIN', 'SNG', 'SATELLITE')
     OR v_table_variant NOT IN ('nlh', 'plo4', 'plo5', 'plo6', 'plo8', 'short_deck', 'flh', 'flo8')
     OR v_requested_current_players <> 0
     OR v_requested_status <> 'REGISTERING'
     OR NULLIF(p_config->>'spin_multiplier', '') IS NOT NULL
     OR (
       p_config ? 'spin_locked_tiers'
       AND jsonb_typeof(p_config->'spin_locked_tiers') IS DISTINCT FROM 'null'
     )
     OR (v_tournament_type = 'SPIN' AND (v_variant <> 'spin' OR v_max_players <> 3))
     OR (
       v_tournament_type = 'SATELLITE'
       AND (
         v_satellite_target_id IS NULL
         OR v_satellite_seats IS NULL
         OR v_satellite_seats <= 0
         OR v_satellite_seats > v_max_players
       )
     )
     OR (
       v_tournament_type <> 'SATELLITE'
       AND (v_satellite_target_id IS NOT NULL OR v_satellite_seats IS NOT NULL)
     )
     OR v_buy_in < 0 OR v_buy_in_fee < 0 OR v_guarantee < 0 THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_CONFIG'
      USING ERRCODE = '22023';
  END IF;

  v_first_level := v_blinds->0;
  v_small_blind := COALESCE(
    NULLIF(v_first_level->>'smallBlind', '')::numeric,
    NULLIF(v_first_level->>'small_blind', '')::numeric,
    NULLIF(v_first_level->>'sb', '')::numeric
  );
  v_big_blind := COALESCE(
    NULLIF(v_first_level->>'bigBlind', '')::numeric,
    NULLIF(v_first_level->>'big_blind', '')::numeric,
    NULLIF(v_first_level->>'bb', '')::numeric
  );
  IF v_small_blind IS NULL OR v_small_blind <= 0
     OR v_big_blind IS NULL OR v_big_blind < v_small_blind THEN
    RAISE EXCEPTION 'SEAT_FIRST_CREATE_INVALID_BLINDS'
      USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_existing
    FROM public.tournaments t
   WHERE t.id = p_tournament_id
   FOR UPDATE;
  IF FOUND THEN
    SELECT count(*) INTO v_existing_table_count
      FROM public.tables tb
     WHERE tb.tournament_id = p_tournament_id
       AND COALESCE(tb.is_deleted, false) = false
       AND tb.status IN ('waiting', 'running');

    IF v_existing_table_count <> 1 THEN
      RAISE EXCEPTION
        'SEAT_FIRST_ATOMIC_PARTIAL_STATE: tournament % has % joinable tables',
        p_tournament_id, v_existing_table_count
        USING ERRCODE = '23514';
    END IF;

    SELECT tb.* INTO v_existing_table
      FROM public.tables tb
     WHERE tb.tournament_id = p_tournament_id
       AND COALESCE(tb.is_deleted, false) = false
       AND tb.status IN ('waiting', 'running')
     ORDER BY tb.created_at, tb.id
     LIMIT 1
     FOR UPDATE;
    v_table_id := v_existing_table.id;

    IF v_existing.club_id IS DISTINCT FROM v_club_id
       OR v_existing.union_id IS DISTINCT FROM v_union_id
       OR v_existing.name IS DISTINCT FROM v_name
       OR lower(v_existing.game_type) IS DISTINCT FROM lower(v_game_type)
       OR lower(v_existing.variant) IS DISTINCT FROM v_variant
       OR upper(v_existing.tournament_type) IS DISTINCT FROM v_tournament_type
       OR v_existing.buy_in_amount IS DISTINCT FROM v_buy_in
       OR v_existing.buy_in_fee IS DISTINCT FROM v_buy_in_fee
       OR v_existing.guaranteed_prize IS DISTINCT FROM v_guarantee
       OR v_existing.starting_chips IS DISTINCT FROM v_starting_chips
       OR v_existing.max_players IS DISTINCT FROM v_max_players
       OR v_existing.min_players IS DISTINCT FROM v_min_players
       OR v_existing.table_size IS DISTINCT FROM v_table_size
       OR (v_existing.blind_structure)::jsonb IS DISTINCT FROM v_blinds
       OR (v_existing.payout_structure)::jsonb IS DISTINCT FROM v_payouts
       OR v_existing.start_time IS DISTINCT FROM v_start_time
       OR v_existing.late_reg_levels IS DISTINCT FROM v_late_reg_levels
       OR v_existing.late_reg_mins IS DISTINCT FROM v_late_reg_mins
       OR v_existing.satellite_target_id IS DISTINCT FROM v_satellite_target_id
       OR v_existing.satellite_seats IS DISTINCT FROM v_satellite_seats
       OR v_existing.short_description IS DISTINCT FROM v_short_description
       OR v_existing_table.club_id IS DISTINCT FROM v_club_id
       OR v_existing_table.tournament_id IS DISTINCT FROM p_tournament_id
       OR v_existing_table.name IS DISTINCT FROM v_name
       OR lower(v_existing_table.game_type) IS DISTINCT FROM 'tournament'
       OR lower(v_existing_table.game_variant) IS DISTINCT FROM v_table_variant
       OR v_existing_table.stakes IS DISTINCT FROM
          (v_small_blind::text || '/' || v_big_blind::text)
       OR v_existing_table.small_blind IS DISTINCT FROM v_small_blind
       OR v_existing_table.big_blind IS DISTINCT FROM v_big_blind
       OR v_existing_table.min_buy_in IS DISTINCT FROM 0::numeric
       OR v_existing_table.max_buy_in IS DISTINCT FROM 0::numeric
       OR v_existing_table.max_players IS DISTINCT FROM v_max_players THEN
      RAISE EXCEPTION 'SEAT_FIRST_CREATE_IDEMPOTENCY_MISMATCH: %', p_tournament_id
        USING ERRCODE = '22023';
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'replayed', true,
      'tournament', to_jsonb(v_existing),
      'table_id', v_table_id
    );
  END IF;

  IF v_admission_abi='unlimited-mtt-v2' AND v_satellite_target_id IS NOT NULL THEN
    RAISE EXCEPTION 'NEW_SATELLITE_REQUIRES_SCHEDULED_MTT_CONFIG' USING ERRCODE='55000';
  END IF;

  INSERT INTO public.tournaments (
    id, club_id, union_id, name, game_type, variant, tournament_type,
    buy_in_amount, buy_in_fee, guaranteed_prize, starting_chips,
    max_players, min_players, table_size, current_players, status,
    blind_structure, payout_structure, start_time,
    late_reg_levels, late_reg_mins,
    satellite_target_id, satellite_seats, short_description
  ) VALUES (
    p_tournament_id, v_club_id, v_union_id, v_name, v_game_type, v_variant,
    v_tournament_type, v_buy_in, v_buy_in_fee, v_guarantee, v_starting_chips,
    v_max_players, v_min_players, v_table_size, 0, 'REGISTERING',
    v_blinds::text, v_payouts::text, v_start_time,
    v_late_reg_levels, v_late_reg_mins,
    v_satellite_target_id, v_satellite_seats, v_short_description
  ) RETURNING * INTO v_created;

  INSERT INTO public.tables (
    club_id, tournament_id, name, game_type, game_variant, stakes,
    small_blind, big_blind, min_buy_in, max_buy_in,
    max_players, current_players, status
  ) VALUES (
    v_club_id, p_tournament_id, v_name, 'tournament', v_table_variant,
    v_small_blind::text || '/' || v_big_blind::text,
    v_small_blind, v_big_blind, 0, 0,
    v_max_players, 0, 'waiting'
  ) RETURNING id INTO v_table_id;

  RETURN jsonb_build_object(
    'ok', true,
    'replayed', false,
    'tournament', to_jsonb(v_created),
    'table_id', v_table_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_fence_welcome_package_schedule_spawn()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_retired timestamptz; v_active boolean;
BEGIN
  IF NEW.schedule_id IS NOT NULL THEN
    SELECT i.retired_at INTO v_retired FROM public.club_welcome_package_items i
     WHERE i.entity_kind='tournament_schedule' AND i.entity_id=NEW.schedule_id
     FOR KEY SHARE;
    IF FOUND THEN
      SELECT s.active INTO v_active FROM public.tournament_schedules s
       WHERE s.id=NEW.schedule_id FOR KEY SHARE;
      IF NOT FOUND OR v_retired IS NOT NULL OR v_active IS NOT TRUE THEN
        RAISE EXCEPTION 'WELCOME_PACKAGE_SCHEDULE_RETIRED' USING ERRCODE='55000';
      END IF;
    END IF;
  END IF;
  IF NEW.club_id IS NOT NULL
     AND upper(COALESCE(NEW.tournament_type::text,'')) IN('SPIN','SNG')
     AND EXISTS(SELECT 1 FROM public.club_welcome_package_receipts r WHERE r.club_id=NEW.club_id) THEN
    SELECT p.is_active INTO v_active FROM public.spin_bonus_pools p
     WHERE p.club_id=NEW.club_id FOR KEY SHARE;
    IF NOT FOUND OR v_active IS NOT TRUE THEN
      RAISE EXCEPTION 'WELCOME_PACKAGE_SPIN_BOARD_RETIRED' USING ERRCODE='55000';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_guard_retired_club_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_club_id uuid;
  v_old_club_id uuid;
  v_maintenance boolean :=
    auth.uid() IS NULL
    AND coalesce(current_setting('app.club_retirement_maintenance', true), '') = 'on';
BEGIN
  IF v_maintenance THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := OLD.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = OLD.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr WHERE cr.id = OLD.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
    ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
      SELECT s.club_id INTO v_club_id FROM public.tournament_schedules s WHERE s.id = OLD.schedule_id;
    ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
      IF OLD.game_kind = 'table' THEN
        SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = OLD.game_id;
      ELSE
        SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = OLD.game_id;
      END IF;
    ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
      IF OLD.host_kind = 'club' THEN v_club_id := OLD.host_id; END IF;
    ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.wheel_configs c
       WHERE c.host_id=OLD.host_id AND c.host_kind='club';
    ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.diamond_game_configs c
       WHERE c.host_id=OLD.host_id AND c.game=OLD.game AND c.host_kind='club';
    ELSE
      v_club_id := OLD.club_id;
    END IF;
  ELSE
    IF TG_TABLE_NAME = 'unions' THEN
      v_club_id := NEW.id;
    ELSIF TG_TABLE_NAME = 'table_seats' THEN
      SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.table_id;
    ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
      SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = NEW.tournament_id;
    ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
      SELECT cr.club_id INTO v_club_id FROM public.cashout_requests cr WHERE cr.id = NEW.cashout_request_id;
    ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
      SELECT a.club_id INTO v_club_id FROM public.agents a WHERE a.id = NEW.agent_id;
    ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
      SELECT s.club_id INTO v_club_id FROM public.tournament_schedules s WHERE s.id = NEW.schedule_id;
    ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
      IF NEW.game_kind = 'table' THEN
        SELECT t.club_id INTO v_club_id FROM public.tables t WHERE t.id = NEW.game_id;
      ELSE
        SELECT t.club_id INTO v_club_id FROM public.tournaments t WHERE t.id = NEW.game_id;
      END IF;
    ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
      IF NEW.host_kind = 'club' THEN v_club_id := NEW.host_id; END IF;
    ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.wheel_configs c
       WHERE c.host_id=NEW.host_id AND c.host_kind='club';
    ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
      SELECT c.host_id INTO v_club_id FROM public.diamond_game_configs c
       WHERE c.host_id=NEW.host_id AND c.game=NEW.game AND c.host_kind='club';
    ELSE
      v_club_id := NEW.club_id;
    END IF;

    IF TG_OP = 'UPDATE' THEN
      IF TG_TABLE_NAME = 'unions' THEN
        v_old_club_id := OLD.id;
      ELSIF TG_TABLE_NAME = 'table_seats' THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.table_id;
      ELSIF TG_TABLE_NAME IN ('tournament_players', 'tournament_escrow') THEN
        SELECT t.club_id INTO v_old_club_id FROM public.tournaments t WHERE t.id = OLD.tournament_id;
      ELSIF TG_TABLE_NAME = 'chip_escrow' THEN
        SELECT cr.club_id INTO v_old_club_id FROM public.cashout_requests cr WHERE cr.id = OLD.cashout_request_id;
      ELSIF TG_TABLE_NAME = 'credit_invoices' THEN
        SELECT a.club_id INTO v_old_club_id FROM public.agents a WHERE a.id = OLD.agent_id;
      ELSIF TG_TABLE_NAME = 'tournament_schedule_spawns' THEN
        SELECT s.club_id INTO v_old_club_id FROM public.tournament_schedules s WHERE s.id = OLD.schedule_id;
      ELSIF TG_TABLE_NAME = 'managed_game_schedules' THEN
        IF OLD.game_kind = 'table' THEN
          SELECT t.club_id INTO v_old_club_id FROM public.tables t WHERE t.id = OLD.game_id;
        ELSE
          SELECT t.club_id INTO v_old_club_id FROM public.tournaments t WHERE t.id = OLD.game_id;
        END IF;
      ELSIF TG_TABLE_NAME IN ('wheel_configs','diamond_game_configs') THEN
        IF OLD.host_kind = 'club' THEN v_old_club_id := OLD.host_id; END IF;
      ELSIF TG_TABLE_NAME = 'wheel_pools' THEN
        SELECT c.host_id INTO v_old_club_id FROM public.wheel_configs c
         WHERE c.host_id=OLD.host_id AND c.host_kind='club';
      ELSIF TG_TABLE_NAME = 'diamond_game_pools' THEN
        SELECT c.host_id INTO v_old_club_id FROM public.diamond_game_configs c
         WHERE c.host_id=OLD.host_id AND c.game=OLD.game AND c.host_kind='club';
      ELSE
        v_old_club_id := OLD.club_id;
      END IF;
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'unions' AND v_club_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:' || v_club_id::text, 0));
  END IF;

  -- Lock both scopes in UUID order.  A writer that began just before retirement
  -- waits here and then observes the committed retired lifecycle.
  PERFORM 1
    FROM public.clubs c
   WHERE c.id IN (v_club_id, v_old_club_id)
   ORDER BY c.id
   FOR KEY SHARE;

  -- These two owning stores have no club FK. Recheck after the shared
  -- parent lock: cleanup may have deleted that parent while this writer waited.
  IF TG_OP <> 'DELETE' AND TG_TABLE_NAME IN ('cash_games','tournament_schedules')
     AND v_club_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.clubs WHERE id=v_club_id) THEN
    RAISE EXCEPTION 'CLUB_NOT_FOUND: game records require their owning club'
      USING ERRCODE='23503';
  END IF;

  IF (v_club_id IS NOT NULL OR v_old_club_id IS NOT NULL) AND EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id IN (v_club_id, v_old_club_id) AND c.lifecycle_status = 'retired'
  ) THEN
    RAISE EXCEPTION 'CLUB_RETIRED: gameplay and cashier records are read-only'
      USING ERRCODE = '55000';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.fn_remove_first_club_welcome_games(p_club_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_owner uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok',false,'replayed',false,'club_id',p_club_id,'reason','authentication_required');
  END IF;
  SELECT owner_id INTO v_owner FROM public.clubs WHERE id=p_club_id;
  IF v_owner IS DISTINCT FROM v_actor THEN
    RETURN jsonb_build_object('ok',false,'replayed',false,'club_id',p_club_id,'reason','owner_only');
  END IF;
  RETURN public.fn_unwind_unused_first_club_welcome_package(p_club_id,p_operation_id);
EXCEPTION WHEN SQLSTATE '55000' THEN
  RETURN jsonb_build_object('ok',false,'replayed',false,'club_id',p_club_id,
    'reason',SQLERRM);
END $function$

CREATE OR REPLACE FUNCTION public.fn_unwind_unused_first_club_welcome_package(p_club_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid:=COALESCE(auth.uid(),(SELECT actor_id FROM public.club_welcome_package_receipts WHERE club_id=p_club_id));
  v_prior public.club_welcome_reset_receipts%ROWTYPE;
  v_cash uuid[]:='{}'; v_schedules uuid[]:='{}'; v_tournaments uuid[]:='{}'; v_tables uuid[]:='{}';
  v_bbj public.bbj_pools%ROWTYPE; v_spin public.spin_bonus_pools%ROWTYPE;
  v_bbj_funding numeric; v_spin_funding numeric; v_after numeric; v_spin_result jsonb;
  v_saved jsonb; v_result jsonb;
  v_cancel_id uuid; v_cancel jsonb;
BEGIN
  IF p_club_id IS NULL OR p_operation_id IS NULL THEN
    RAISE EXCEPTION 'WELCOME_UNWIND_REQUIRES_CLUB_AND_OPERATION';
  END IF;
  SELECT * INTO v_prior FROM public.club_welcome_reset_receipts
   WHERE operation_id=p_operation_id;
  IF FOUND THEN
    IF v_prior.club_id IS DISTINCT FROM p_club_id THEN
      RAISE EXCEPTION 'WELCOME_UNWIND_OPERATION_PAYLOAD_MISMATCH';
    END IF;
    RETURN v_prior.result||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO v_prior FROM public.club_welcome_reset_receipts
   WHERE club_id=p_club_id AND COALESCE((result->>'ok')::boolean,false) IS TRUE
   ORDER BY completed_at DESC LIMIT 1;
  IF FOUND THEN
    RETURN v_prior.result||jsonb_build_object('replayed',true,'requested_operation_id',p_operation_id);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.club_welcome_package_receipts WHERE club_id=p_club_id) THEN
    RETURN jsonb_build_object('ok',true,'club_id',p_club_id,'reason','no_welcome_package','replayed',false);
  END IF;

  PERFORM public.fn_ca_lock_settlement_lane_global();
  PERFORM 1 FROM public.clubs WHERE id=p_club_id FOR UPDATE;
  PERFORM 1 FROM public.club_welcome_package_items
   WHERE club_id=p_club_id ORDER BY slot_key FOR UPDATE;
  SELECT amount INTO v_bbj_funding FROM public.club_welcome_package_funding
   WHERE club_id=p_club_id AND destination='bbj_main' FOR UPDATE;
  SELECT amount INTO v_spin_funding FROM public.club_welcome_package_funding
   WHERE club_id=p_club_id AND destination='spin_reserve' FOR UPDATE;
  SELECT * INTO v_bbj FROM public.bbj_pools WHERE club_id=p_club_id AND union_id IS NULL FOR UPDATE;
  SELECT * INTO v_spin FROM public.spin_bonus_pools WHERE club_id=p_club_id FOR UPDATE;
  SELECT COALESCE(array_agg(entity_id ORDER BY entity_id),'{}') INTO v_cash
    FROM public.club_welcome_package_items
   WHERE club_id=p_club_id AND entity_kind='cash_game' AND retired_at IS NULL;
  SELECT COALESCE(array_agg(entity_id ORDER BY entity_id),'{}') INTO v_schedules
    FROM public.club_welcome_package_items
   WHERE club_id=p_club_id AND entity_kind='tournament_schedule' AND retired_at IS NULL;
  PERFORM 1 FROM public.tournament_schedules WHERE id=ANY(v_schedules) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournament_schedule_spawns
   WHERE schedule_id=ANY(v_schedules) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournaments t
   WHERE t.club_id=p_club_id AND (
     upper(COALESCE(t.tournament_type::text,'')) IN('SPIN','SNG','SATELLITE')
     OR t.schedule_id=ANY(v_schedules) OR EXISTS(
       SELECT 1 FROM public.tournament_schedule_spawns sp
        WHERE sp.tournament_id=t.id AND sp.schedule_id=ANY(v_schedules)
     )
   ) ORDER BY t.id FOR UPDATE;
  IF NOT (WITH expected(name,game_type,variant,tournament_type,buy_in_amount,buy_in_fee,seats,stack) AS (
    VALUES
      ('NLH Heads-Up 1','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('PLO4 Heads-Up 1','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('NLH Heads-Up 1 Turbo','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('PLO4 Heads-Up 1 Turbo','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('1 Chip Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Deep Stack Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,1000)
  ), candidates AS (
    SELECT e.name FROM public.tournaments t JOIN expected e
      ON t.name=e.name AND upper(COALESCE(t.game_type,''))=e.game_type
     AND lower(COALESCE(t.variant,''))=e.variant
     AND upper(COALESCE(t.tournament_type::text,''))=e.tournament_type
     AND t.buy_in_amount=e.buy_in_amount AND t.buy_in_fee=e.buy_in_fee
     AND t.max_players=e.seats AND t.min_players=e.seats
     AND t.table_size=e.seats AND t.starting_chips=e.stack
     WHERE t.club_id=p_club_id AND t.union_id IS NULL AND t.schedule_id IS NULL
       AND t.restart_source_id IS NULL AND t.satellite_target_id IS NULL
       AND t.satellite_target IS NULL
  ) SELECT count(*)=count(DISTINCT name) FROM candidates) THEN
    RAISE EXCEPTION 'WELCOME_PACKAGE_BOARD_LINEAGE_AMBIGUOUS' USING ERRCODE='55000';
  END IF;
  WITH package_schedule_tournaments AS (
    SELECT t.id FROM public.tournaments t
     WHERE t.club_id=p_club_id AND t.schedule_id=ANY(v_schedules)
    UNION
    SELECT t.id FROM public.tournament_schedule_spawns sp
    JOIN public.tournaments t ON t.id=sp.tournament_id
     WHERE sp.schedule_id=ANY(v_schedules) AND t.club_id=p_club_id
  ), expected(name,game_type,variant,tournament_type,buy_in_amount,buy_in_fee,seats,stack) AS (
    VALUES
      ('NLH Heads-Up 1','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('PLO4 Heads-Up 1','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,1000),
      ('NLH Heads-Up 1 Turbo','NLH','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('PLO4 Heads-Up 1 Turbo','PLO4','sng','SNG',0.95::numeric,0.05::numeric,2,300),
      ('1 Chip Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,300),
      ('1 Chip Deep Stack Spin NLH','NLH','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO4','PLO4','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO5','PLO5','spin','SPIN',1::numeric,0::numeric,3,1000),
      ('1 Chip Deep Stack Spin PLO6','PLO6','spin','SPIN',1::numeric,0::numeric,3,1000)
  )
  SELECT COALESCE(array_agg(q.id ORDER BY q.id),'{}') INTO v_tournaments FROM (
    SELECT p.id FROM package_schedule_tournaments p
    UNION
    SELECT t.id FROM public.tournaments t JOIN expected e
      ON t.name=e.name AND upper(COALESCE(t.game_type,''))=e.game_type
     AND lower(COALESCE(t.variant,''))=e.variant
     AND upper(COALESCE(t.tournament_type::text,''))=e.tournament_type
     AND t.buy_in_amount=e.buy_in_amount AND t.buy_in_fee=e.buy_in_fee
     AND t.max_players=e.seats AND t.min_players=e.seats
     AND t.table_size=e.seats AND t.starting_chips=e.stack
     WHERE t.club_id=p_club_id AND t.union_id IS NULL AND t.schedule_id IS NULL
       AND t.restart_source_id IS NULL AND t.satellite_target_id IS NULL
       AND t.satellite_target IS NULL
    UNION
    SELECT t.id FROM public.tournaments t
     WHERE t.club_id=p_club_id AND t.union_id IS NULL
       AND upper(COALESCE(t.tournament_type::text,''))='SATELLITE'
       AND EXISTS(
         SELECT 1 FROM package_schedule_tournaments target
          WHERE target.id=t.satellite_target_id OR target.id=t.satellite_target
       )
  ) q;
  SELECT COALESCE(array_agg(id ORDER BY id),'{}') INTO v_tables
    FROM public.tables WHERE cluster_id=ANY(v_cash) OR tournament_id=ANY(v_tournaments);

  PERFORM 1 FROM public.tournament_schedules WHERE id=ANY(v_schedules) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.cash_games WHERE id=ANY(v_cash) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tournaments WHERE id=ANY(v_tournaments) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.tables WHERE id=ANY(v_tables) ORDER BY id FOR UPDATE;

  IF EXISTS(SELECT 1 FROM public.table_seats WHERE table_id=ANY(v_tables) AND left_at IS NULL)
     OR EXISTS(SELECT 1 FROM public.table_sessions WHERE table_id=ANY(v_tables) AND COALESCE(is_active,false) AND left_at IS NULL)
     OR EXISTS(SELECT 1 FROM public.table_waitlist WHERE table_id=ANY(v_tables) AND status IN('waiting','notified'))
     OR EXISTS(SELECT 1 FROM public.cash_game_waitlist WHERE game_id=ANY(v_cash) AND status IN('waiting','notified'))
     OR EXISTS(SELECT 1 FROM public.tournament_players WHERE tournament_id=ANY(v_tournaments))
     OR EXISTS(SELECT 1 FROM public.hand_history h
          WHERE h.tournament_id=ANY(v_tournaments))
     OR EXISTS(SELECT 1 FROM public.hand_history h
          WHERE h.table_id=ANY(v_tables))
     OR EXISTS(SELECT 1 FROM public.cash_seat_moves WHERE game_id=ANY(v_cash))
     OR EXISTS(SELECT 1 FROM public.cash_seat_change_requests WHERE game_id=ANY(v_cash))
     OR EXISTS(SELECT 1 FROM public.managed_game_schedules WHERE status='executing' AND
          ((game_kind='tournament' AND game_id=ANY(v_tournaments)) OR
           (game_kind='table' AND game_id=ANY(v_tables)))) THEN
    RAISE EXCEPTION 'WELCOME_PACKAGE_HAS_PLAY_OR_REGISTRATION_HISTORY' USING ERRCODE='55000';
  END IF;

  IF v_bbj_funding IS DISTINCT FROM 100 OR v_spin_funding IS DISTINCT FROM 200
     OR v_bbj.id IS NULL OR v_bbj.main_balance IS DISTINCT FROM v_bbj_funding
     OR COALESCE(v_bbj.backup_balance,0)<>0 OR COALESCE(v_bbj.promo_balance,0)<>0
     OR COALESCE(v_bbj.total_contributed,0)<>0 OR COALESCE(v_bbj.total_paid_out,0)<>0
     OR COALESCE(v_bbj.hit_count,0)<>0
     OR EXISTS(SELECT 1 FROM public.bbj_contributions WHERE pool_id=v_bbj.id)
     OR EXISTS(SELECT 1 FROM public.bbj_payouts WHERE pool_id=v_bbj.id)
     OR EXISTS(SELECT 1 FROM public.wallet_credit_idempotency i
          WHERE i.key LIKE 'bbjpromo:'||v_bbj.id::text||':%')
     OR v_spin.id IS NULL OR v_spin.balance IS DISTINCT FROM v_spin_funding
     OR v_spin.seeded_amount IS DISTINCT FROM v_spin_funding THEN
    RAISE EXCEPTION 'WELCOME_PACKAGE_ECONOMICS_ARE_NOT_PRISTINE' USING ERRCODE='55000';
  END IF;
  IF EXISTS(SELECT 1 FROM public.wheel_pools WHERE host_id=p_club_id
      AND (spins<>0 OR intake_diamonds<>0 OR chips_minted<>0 OR chips_paid<>0 OR diamonds_paid<>0))
     OR EXISTS(SELECT 1 FROM public.diamond_game_pools WHERE host_id=p_club_id
      AND (rounds<>0 OR intake_diamonds<>0 OR chips_minted<>0 OR chips_paid<>0 OR reserved_chips<>0)) THEN
    RAISE EXCEPTION 'WELCOME_DIAMOND_GAMES_ARE_NOT_UNUSED' USING ERRCODE='55000';
  END IF;

  -- Stop every recurrence source before cancelling unused materializations.
  UPDATE public.spin_bonus_pools SET is_active=false,deactivated_at=now(),updated_at=now()
   WHERE club_id=p_club_id;
  UPDATE public.tournament_schedules SET active=false,updated_at=now() WHERE id=ANY(v_schedules);
  UPDATE public.wheel_configs SET enabled=false,updated_at=now(),updated_by=v_actor WHERE host_id=p_club_id;
  UPDATE public.diamond_game_configs SET enabled=false,updated_at=now(),updated_by=v_actor WHERE host_id=p_club_id;
  UPDATE public.clubs SET spins_enabled=false,bbj_enabled=false,bbj_rake_enabled=false,updated_at=now()
   WHERE id=p_club_id;

  PERFORM set_config('app.managed_game_lifecycle','on',true);
  UPDATE public.cash_games SET enabled=false,state='dormant',closed_at=COALESCE(closed_at,now()),
    closed_by=v_actor,updated_at=now() WHERE id=ANY(v_cash);
  -- A cancellation is a terminal settlement with an immutable receipt
  -- (deferred trigger tournaments_cancel_must_refund). Use the receipted door
  -- fn_close_managed_game uses; the global lane and lifecycle flag are held.
  FOR v_cancel_id IN SELECT t.id FROM public.tournaments t
     WHERE t.id=ANY(v_tournaments)
       AND upper(COALESCE(t.status::text,'')) NOT IN('COMPLETED','CANCELLED','CANCELED')
     ORDER BY t.id LOOP
    v_cancel:=public.atomic_cancel_tournament(v_cancel_id,v_actor);
    IF v_cancel->>'ok' IS DISTINCT FROM 'true'
       OR v_cancel->>'fully_settled' IS DISTINCT FROM 'true'
       OR v_cancel->>'status' IS DISTINCT FROM 'CANCELLED'
       OR v_cancel->>'tournament_id' IS DISTINCT FROM v_cancel_id::text
       OR COALESCE((v_cancel->>'source_player_count')::integer,-1)<>0 THEN
      RAISE EXCEPTION 'WELCOME_TOURNAMENT_CANCELLATION_RECEIPT_REFUSED: %',v_cancel_id
        USING ERRCODE='55000';
    END IF;
  END LOOP;
  UPDATE public.tables SET status='closed',current_players=0,updated_at=now()
   WHERE id=ANY(v_tables) AND lower(COALESCE(status,'')) NOT IN('closed','completed','cancelled','finished');
  UPDATE public.managed_game_schedules SET status='cancelled',completed_at=now(),
    result=jsonb_build_object('ok',false,'reason','welcome_package_reset')
   WHERE status IN('scheduled','executing') AND
    ((game_kind='tournament' AND game_id=ANY(v_tournaments)) OR (game_kind='table' AND game_id=ANY(v_tables)));

  v_spin_result:=public.fn_spin_deactivate(p_club_id,v_actor);
  IF COALESCE((v_spin_result->>'seed_returned')::numeric,0) IS DISTINCT FROM v_spin_funding THEN
    RAISE EXCEPTION 'WELCOME_SPIN_SEED_RETURN_REFUSED';
  END IF;

  v_saved:=public.fn_ca_ledger_declaration_save(ARRAY['bbj_pools']);
  PERFORM public.fn_ca_declare_ledger('treasury_transfer','bbj_pool',v_bbj.id,
    NULL,NULL,ARRAY['bbj_pools']);
  v_after:=public.fn_spin_move_owner_wallet(p_club_id,'club','chip_treasury',v_bbj_funding);
  IF v_after IS NULL THEN RAISE EXCEPTION 'WELCOME_BBJ_RETURN_REFUSED'; END IF;
  INSERT INTO public.chip_transactions
    (id,club_id,amount,transaction_type,notes,balance_after,metadata)
  VALUES(gen_random_uuid(),p_club_id,v_bbj_funding,'bbj_promo_sweep',
    'Unused welcome-package BBJ principal returned to club treasury',v_after,
    jsonb_build_object('reason','welcome_package_reset','operation_id',p_operation_id,'pool_id',v_bbj.id));
  UPDATE public.bbj_pools SET main_balance=0,backup_balance=0,promo_balance=0,status='retired',updated_at=now()
   WHERE id=v_bbj.id;
  PERFORM public.fn_ca_ledger_declaration_restore(v_saved);

  UPDATE public.club_welcome_package_items SET retired_at=now(),reset_operation_id=p_operation_id
   WHERE club_id=p_club_id AND retired_at IS NULL;
  v_result:=jsonb_build_object('ok',true,'replayed',false,'club_id',p_club_id,
    'package_version','welcome-v1','operation_id',p_operation_id,'opening_grant_unwound',false,
    'returned_to_treasury',jsonb_build_object('bbj',v_bbj_funding,'spin',v_spin_funding),
    'removed',jsonb_build_object('cash_game_ids',to_jsonb(v_cash),'schedule_ids',to_jsonb(v_schedules),
      'tournament_ids',to_jsonb(v_tournaments),'table_ids',to_jsonb(v_tables)),
    'owner_acceptance_required',true,'owner_acceptance_receipts_preserved',true,
    'completed_at',transaction_timestamp());
  INSERT INTO public.club_welcome_reset_receipts(club_id,operation_id,actor_id,result)
  VALUES(p_club_id,p_operation_id,v_actor,v_result);
  RETURN v_result;
END $function$
